(() => {
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=v=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v);
 const arrow='<span class="action-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></span>';
 const fuel={electric:'Electric',mild_hybrid:'Mild hybrid',full_hybrid:'Full hybrid',plug_in_hybrid:'Plug-in hybrid',petrol:'Petrol',diesel:'Diesel',unknown:'Not explicit in source row'};
 window.renderModelSourceDetails=m=>`<section class="catalogue-source-details" aria-label="Full ${e(m.brand+' '+m.model)} source information"><details class="catalogue-versions" open><summary><span>Versions & published prices <small>${m.versions?.length||0} priced entries</small></span><span aria-hidden="true">+</span></summary><div class="catalogue-table-wrap"><table><caption>Prices are for the individual versions below. Confirm final equipment and availability with Unicars.</caption><thead><tr><th scope="col">Version</th><th scope="col">Engine type</th><th scope="col">Gearbox</th><th scope="col">List price</th></tr></thead><tbody>${(m.versions||[]).map(v=>`<tr><td>${e(v.trim)}</td><td>${fuel[v.powertrain]||fuel.unknown}</td><td>${v.transmission?e(v.transmission==='automatic'?'Automatic':'Manual'):'See PDF'}</td><td>${money(v.price)}</td></tr>`).join('')}</tbody></table></div></details><details class="catalogue-full-document"><summary><span>Technical details & equipment</span><span aria-hidden="true">+</span></summary><div class="catalogue-document-body"><p>Read the complete original document, including its technical tables, equipment, optional extras and terms.</p><a class="button secondary" href="${e(m.document)}" target="_blank" rel="noopener"><span>Open the complete PDF</span>${arrow}</a><iframe src="${e(m.document)}#view=FitH" title="Complete ${e(m.brand+' '+m.model)} specifications and equipment PDF" loading="lazy"></iframe><div class="catalogue-document-search" data-source-text="${e(m.documentText)}" data-source-pdf="${e(m.document)}"><label>Find a specification<input type="search" placeholder="Try dimensions, luggage or charging" aria-label="Search this model’s full specification document"></label><div role="status" aria-live="polite" class="catalogue-document-matches"></div></div></div></details>${m.campaigns?.length?`<details class="catalogue-campaigns"><summary><span>Published campaign material <small>${m.campaigns.length} campaign${m.campaigns.length===1?'':'s'}</small></span><span aria-hidden="true">+</span></summary><div>${m.campaigns.map(c=>`<article>${c.image?`<img src="${e(c.image)}" alt="Original published ${e(m.brand+' '+m.model)} campaign poster" loading="lazy">`:''}<p>Original campaign checked 20 November 2026. Campaign conditions may differ from the standard list price; confirm eligibility and terms with Unicars.</p><a class="button secondary" href="${e(c.source)}" target="_blank" rel="noopener"><span>View the original campaign</span>${arrow}</a></article>`).join('')}</div></details>`:''}</section>`;
 const cache=new Map();let request=0;
 document.addEventListener('input',async event=>{const input=event.target;if(!input.matches('.catalogue-document-search input'))return;const root=input.closest('.catalogue-document-search'),out=root.querySelector('.catalogue-document-matches'),q=input.value.trim().toLocaleLowerCase(),seq=++request;if(q.length<2){out.innerHTML='';return}out.textContent='Searching the full document…';try{const url=root.dataset.sourceText;let data=cache.get(url);if(!data){const r=await fetch(url);if(!r.ok)throw Error();data=await r.json();cache.set(url,data)}if(seq!==request||!root.isConnected)return;const found=data.pages.filter(p=>p.text.toLocaleLowerCase().includes(q));out.innerHTML=found.length?`<p>${found.length} matching page${found.length===1?'':'s'}</p>`+found.map(p=>{const at=p.text.toLocaleLowerCase().indexOf(q),snippet=p.text.slice(Math.max(0,at-80),at+q.length+130).replace(/\s+/g,' ');return `<article><p>${e(snippet)}</p><a class="button secondary" href="${e(root.dataset.sourcePdf)}#page=${p.page}" target="_blank" rel="noopener"><span>Open page ${p.page}</span>${arrow}</a></article>`}).join(''):'<p>No matching text was found. Check the original PDF for diagrams and image-only information.</p>'}catch(err){if(seq===request)out.textContent='The text search could not load. The complete PDF is still available above.'}});
})();
